13	+
14	+/** Corporate partnership: companies get a discount based on their agreement. */
15	+public final class CorporateRatePlanStrategy implements RatePlanStrategy {
16	+
17	+    private static final Map<String, BigDecimal> COMPANY_DISCOUNTS = Map.of(
18	+            "TECNOSUL", new BigDecimal("0.12"),
19	+            "AGROVALE", new BigDecimal("0.18"),
20	+            "FARMAVIDA", new BigDecimal("0.25"));
21	+
22	+    @Override
23	+    public void validate(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
24	+        if (companyCode == null || companyCode.isBlank()) {
25	+            throw new HotelException(
26	+                    ErrorCode.INVALID_REQUEST, "corporate rate plan requires a company code");
27	+        }
28	+        if (!COMPANY_DISCOUNTS.containsKey(companyCode)) {
29	+            throw new HotelException(
30	+                    ErrorCode.INVALID_REQUEST,
31	+                    "company code " + companyCode + " is not recognized");
32	+        }
33	+    }
34	+
35	+    @Override
36	+    public Price calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
37	+        int nights = 0;
38	+        BigDecimal subtotal = PriceCalculator.cents(BigDecimal.ZERO);
39	+        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
40	+            subtotal = subtotal.add(PriceCalculator.nightPrice(room, night));
41	+            nights++;
42	+        }
43	+        BigDecimal discountRate = COMPANY_DISCOUNTS.get(companyCode);
44	+        BigDecimal discount = PriceCalculator.cents(subtotal.multiply(discountRate));
45	+        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
46	+    }
47	+
48	+    @Override
49	+    public BigDecimal calculateRefund(BigDecimal amountPaid) {
50	+        return amountPaid;
51	+    }
52	+}
