394	+import hotel.rooms.RoomType;
395	+import java.math.BigDecimal;
396	+import java.time.DayOfWeek;
397	+import java.time.LocalDate;
398	+import java.util.Map;
399	+
400	+/** Weekend package: Friday check-in, Sunday check-out, fixed price per room type. */
401	+public final class WeekendPackageRatePlanStrategy implements RatePlanStrategy {
402	+
403	+    private static final Map<RoomType, BigDecimal> PACKAGE_PRICES = Map.of(
404	+            RoomType.STANDARD, new BigDecimal("520.00"),
405	+            RoomType.DELUXE, new BigDecimal("820.00"),
406	+            RoomType.SUITE, new BigDecimal("1200.00"));
407	+
408	+    @Override
409	+    public void validate(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
410	+        if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY) {
411	+            throw new HotelException(
412	+                    ErrorCode.INVALID_REQUEST,
413	+                    "weekend package requires check-in on Friday");
414	+        }
415	+        if (checkOut.getDayOfWeek() != DayOfWeek.SUNDAY) {
416	+            throw new HotelException(
417	+                    ErrorCode.INVALID_REQUEST,
418	+                    "weekend package requires check-out on Sunday");
419	+        }
420	+        long nights = java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
421	+        if (nights != 2) {
422	+            throw new HotelException(
423	+                    ErrorCode.INVALID_REQUEST,
424	+                    "weekend package must be exactly 2 nights (Friday to Sunday)");
425	+        }
426	+    }
427	+
428	+    @Override
429	+    public Price calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
430	+        BigDecimal packagePrice = PACKAGE_PRICES.get(room.type());
431	+        // For weekend package, subtotal = discount = 0, and total is the fixed package price
432	+        return new Price(2, packagePrice, PriceCalculator.cents(BigDecimal.ZERO), packagePrice);
433	+    }
434	+
435	+    @Override
436	+    public BigDecimal calculateRefund(BigDecimal amountPaid) {
437	+        return PriceCalculator.cents(amountPaid.divide(new BigDecimal("2")));
438	+    }
439	+}
