     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.math.BigDecimal;
     8	
     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    static final String HOTEL_NAME = "Pousada Maré Alta";
    13	
    14	    private final Rooms rooms;
    15	    private final ReservationStore store;
    16	    private final PriceCalculator priceCalculator;
    17	    private final EmailSender emailSender;
    18	
    19	    public ReservationService(
    20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    21	        this.rooms = rooms;
    22	        this.store = store;
    23	        this.priceCalculator = priceCalculator;
    24	        this.emailSender = emailSender;
    25	    }
    26	
    27	    public synchronized Reservation create(NewReservation request) {
    28	        if (!request.checkOut().isAfter(request.checkIn())) {
    29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    30	        }
    31	        if (request.guests() < 1) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    33	        }
    34	        Room room = rooms.find(request.roomNumber())
    35	                .orElseThrow(() -> new HotelException(
    36	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    37	        if (request.guests() > room.capacity()) {
    38	            throw new HotelException(
    39	                    ErrorCode.CAPACITY_EXCEEDED,
    40	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    41	        }
    42	        // Validate rate plan rules before checking room availability
    43	        request.ratePlan().strategy().validate(room, request.checkIn(), request.checkOut(), request.companyCode());
    44	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    45	            throw new HotelException(
    46	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    47	        }
    48	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
    49	        return store.add(request, price);
    50	    }
    51	
    52	    public Reservation find(long reservationId) {
    53	        return store.find(reservationId)
    54	                .orElseThrow(() -> new HotelException(
    55	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    56	    }
    57	
    58	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    59	    public synchronized Reservation confirm(long reservationId) {
    60	        Reservation reservation = find(reservationId);
    61	        if (reservation.status() != ReservationStatus.PENDING) {
    62	            throw notAllowed(reservation, "confirm");
    63	        }
    64	        reservation.confirmPayment();
    65	        store.update(reservation);
    66	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    67	        emailSender.send(
    68	                reservation.guest().email(),
    69	                "Reserva confirmada - " + HOTEL_NAME,
    70	                confirmationEmailBody(reservation, receipt));
    71	        return reservation;
    72	    }
    73	
    74	    /**
    75	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    76	     * reservation was never paid, so nothing comes back).
    77	     */
    78	    public synchronized Reservation cancel(long reservationId) {
    79	        Reservation reservation = find(reservationId);
    80	        if (reservation.status() != ReservationStatus.PENDING
    81	                && reservation.status() != ReservationStatus.CONFIRMED) {
    82	            throw notAllowed(reservation, "cancel");
    83	        }
    84	        BigDecimal refund = reservation.ratePlan().strategy().calculateRefund(reservation.amountPaid());
    85	        reservation.cancel(refund);
    86	        store.update(reservation);
    87	        return reservation;
    88	    }
    89	
    90	    public synchronized Reservation checkIn(long reservationId) {
    91	        Reservation reservation = find(reservationId);
    92	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    93	            throw notAllowed(reservation, "check in");
    94	        }
    95	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
    96	        store.update(reservation);
    97	        return reservation;
    98	    }
    99	
   100	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   101	    public synchronized ReservationReceipt checkOut(long reservationId) {
   102	        Reservation reservation = find(reservationId);
   103	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   104	            throw notAllowed(reservation, "check out");
   105	        }
   106	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   107	        store.update(reservation);
   108	        return new ReservationReceipt(reservation, roomOf(reservation));
   109	    }
   110	
   111	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   112	    public ReservationReceipt receiptCopy(long reservationId) {
   113	        Reservation reservation = find(reservationId);
   114	        if (!reservation.isPaid()) {
   115	            throw notAllowed(reservation, "issue a receipt for");
   116	        }
   117	        return new ReservationReceipt(reservation, roomOf(reservation));
   118	    }
   119	
   120	    private Room roomOf(Reservation reservation) {
   121	        return rooms.find(reservation.roomNumber()).orElseThrow();
   122	    }
   123	
   124	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   125	        return "Olá, " + reservation.guest().name() + "!\n\n"
   126	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   127	                + receipt.text() + "\n"
   128	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   129	                + "Até breve!\n";
   130	    }
   131	
   132	    private static HotelException notAllowed(Reservation reservation, String operation) {
   133	        return new HotelException(
   134	                ErrorCode.OPERATION_NOT_ALLOWED,
   135	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   136	    }
   137	}
   138	package hotel.reservations;
   139	
   140	import hotel.rooms.Room;
   141	import java.math.BigDecimal;
   142	import java.math.RoundingMode;
   143	import java.time.LocalDate;
   144	import java.time.Month;
   145	
   146	/**
   147	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
   148	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
   149	 * (half-even) at every step.
   150	 */
   151	public final class PriceCalculator {
   152	
   153	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
   154	
   155	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
   156	        return ratePlan.strategy().calculatePrice(room, checkIn, checkOut, companyCode);
   157	    }
   158	
   159	    public static BigDecimal nightPrice(Room room, LocalDate night) {
   160	        BigDecimal nightlyRate = room.nightlyRate();
   161	        if (isHighSeason(night)) {
   162	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
   163	        }
   164	        return cents(nightlyRate);
   165	    }
   166	
   167	    /** High season: from December 15 to the end of February, and the whole of July. */
   168	    public static boolean isHighSeason(LocalDate date) {
   169	        Month month = date.getMonth();
   170	        return month == Month.JANUARY
   171	                || month == Month.FEBRUARY
   172	                || month == Month.JULY
   173	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
   174	    }
   175	
   176	    public static BigDecimal cents(BigDecimal value) {
   177	        return value.setScale(2, RoundingMode.HALF_EVEN);
   178	    }
   179	}
   180	package hotel.reservations;
   181	
   182	public enum RatePlan {
   183	    /** Full price; the guest gets everything back when cancelling a confirmed reservation. */
   184	    STANDARD(new StandardRatePlanStrategy()),
   185	    /** 15% off, but nothing comes back on cancellation. */
   186	    NON_REFUNDABLE(new NonRefundableRatePlanStrategy()),
   187	    /** Corporate partnership: companies get a discount based on their agreement. */
   188	    CORPORATE(new CorporateRatePlanStrategy()),
   189	    /** Weekend package: Friday check-in, Sunday check-out, fixed price per room type. */
   190	    WEEKEND_PACKAGE(new WeekendPackageRatePlanStrategy()),
   191	    /** Long stay: 7 nights or more, 10% discount, full refund on cancellation. */
   192	    LONG_STAY(new LongStayRatePlanStrategy());
   193	
   194	    private final RatePlanStrategy strategy;
   195	
   196	    RatePlan(RatePlanStrategy strategy) {
   197	        this.strategy = strategy;
   198	    }
   199	
   200	    public RatePlanStrategy strategy() {
   201	        return strategy;
   202	    }
   203	}

