   146	/**
   147	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
   148	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
   149	 * (half-even) at every step.
   150	 */
   151	public final class PriceCalculator {
   152	
   153	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
   154	
   155	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
   156	        return ratePlan.strategy().calculatePrice(room, checkIn, checkOut, companyCode);
   157	    }
   158	
   159	    public static BigDecimal nightPrice(Room room, LocalDate night) {
   160	        BigDecimal nightlyRate = room.nightlyRate();
   161	        if (isHighSeason(night)) {
   162	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
   163	        }
   164	        return cents(nightlyRate);
   165	    }
   166	
   167	    /** High season: from December 15 to the end of February, and the whole of July. */
   168	    public static boolean isHighSeason(LocalDate date) {
   169	        Month month = date.getMonth();
   170	        return month == Month.JANUARY
   171	                || month == Month.FEBRUARY
   172	                || month == Month.JULY
   173	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
   174	    }
   175	
   176	    public static BigDecimal cents(BigDecimal value) {
   177	        return value.setScale(2, RoundingMode.HALF_EVEN);
   178	    }
   179	}
