   186	    NON_REFUNDABLE(new NonRefundableRatePlanStrategy()),
   187	    /** Corporate partnership: companies get a discount based on their agreement. */
   188	    CORPORATE(new CorporateRatePlanStrategy()),
   189	    /** Weekend package: Friday check-in, Sunday check-out, fixed price per room type. */
   190	    WEEKEND_PACKAGE(new WeekendPackageRatePlanStrategy()),
   191	    /** Long stay: 7 nights or more, 10% discount, full refund on cancellation. */
   192	    LONG_STAY(new LongStayRatePlanStrategy());
